script:
(function () {
  'use strict';
  // Owner phase: from 2026 the owner takes Uniform Lifetime RMDs (balance on Dec 31 of the prior
  // year / Table III divisor at the age reached that year) from their RMD starting year through the
  // year of death. Heir phase, same inheritance two ways:
  //  - pre-2020 stretch: divisor = heir's Table I life expectancy at age in the year after death,
  //    minus 1 each year (greater of that and the owner's remaining life expectancy if the owner
  //    died after their RBD); the balance comes out when the divisor reaches 1 or less.
  //  - 10-year rule (SECURE Act; T.D. 10001 final regulations): account empty by the end of the
  //    10th year after death; annual RMDs in years 1-9 if the owner died on or after the RBD.
  // After-tax wealth at the end of the stretch = taxable side fund (after-tax withdrawals invested,
  // earnings taxed yearly) + any balance still in the IRA less tax. Lost deferral = stretch - 10-year.
  // Checked in Node (scratchpad tests): owner born 1952, $500,000, 6%: 2026 RMD at 74 =
  // $500,000 / 25.5 = $19,607.84; heir born 1985 inherits at the end of 2037 and the stretch
  // divisor for 2038 is Table I age 53 = 33.4; with 0% return and 0% taxes both paths are worth
  // the same; with equal tax rates the stretch is never worth less than the 10-year rule.
  // ---- IRS tables and rules (distribution years 2025 and 2026) ----------------------------
  // Single Life Table: IRS Pub. 590-B (2025), Appendix B, Table I (Treas. Reg. 1.401(a)(9)-9(b)).
  var SINGLE_LIFE = [
    84.6, 83.7, 82.8, 81.8, 80.8, 79.8, 78.8, 77.9, 76.9, 75.9,  // ages 0-9
    74.9, 73.9, 72.9, 71.9, 70.9, 69.9, 69.0, 68.0, 67.0, 66.0,  // ages 10-19
    65.0, 64.1, 63.1, 62.1, 61.1, 60.2, 59.2, 58.2, 57.3, 56.3,  // ages 20-29
    55.3, 54.4, 53.4, 52.5, 51.5, 50.5, 49.6, 48.6, 47.7, 46.7,  // ages 30-39
    45.7, 44.8, 43.8, 42.9, 41.9, 41.0, 40.0, 39.0, 38.1, 37.1,  // ages 40-49
    36.2, 35.3, 34.3, 33.4, 32.5, 31.6, 30.6, 29.8, 28.9, 28.0,  // ages 50-59
    27.1, 26.2, 25.4, 24.5, 23.7, 22.9, 22.0, 21.2, 20.4, 19.6,  // ages 60-69
    18.8, 18.0, 17.2, 16.4, 15.6, 14.8, 14.1, 13.3, 12.6, 11.9,  // ages 70-79
    11.2, 10.5, 9.9, 9.3, 8.7, 8.1, 7.6, 7.1, 6.6, 6.1,  // ages 80-89
    5.7, 5.3, 4.9, 4.6, 4.3, 4.0, 3.7, 3.4, 3.2, 3.0,  // ages 90-99
    2.8, 2.6, 2.5, 2.3, 2.2, 2.1, 2.1, 2.1, 2.0, 2.0,  // ages 100-109
    2.0, 2.0, 2.0, 1.9, 1.9, 1.8, 1.8, 1.6, 1.4, 1.1,  // ages 110-119
    1.0  // ages 120-120
  ];
  // Uniform Lifetime Table: IRS Pub. 590-B (2025), Appendix B, Table III (Treas. Reg. 1.401(a)(9)-9(c)).
  var UNIFORM = {
    72: 27.4, 73: 26.5, 74: 25.5, 75: 24.6, 76: 23.7, 77: 22.9, 78: 22.0, 79: 21.1, 80: 20.2,
    81: 19.4, 82: 18.5, 83: 17.7, 84: 16.8, 85: 16.0, 86: 15.2, 87: 14.4, 88: 13.7, 89: 12.9,
    90: 12.2, 91: 11.5, 92: 10.8, 93: 10.1, 94: 9.5, 95: 8.9, 96: 8.4, 97: 7.8, 98: 7.3,
    99: 6.8, 100: 6.4, 101: 6.0, 102: 5.6, 103: 5.2, 104: 4.9, 105: 4.6, 106: 4.3, 107: 4.1,
    108: 3.9, 109: 3.7, 110: 3.5, 111: 3.4, 112: 3.3, 113: 3.1, 114: 3.0, 115: 2.9, 116: 2.8,
    117: 2.7, 118: 2.5, 119: 2.3, 120: 2.0
  };
  // RMD starting age (SECURE 2.0 Act): 72 if born 1950 or earlier, 73 if born 1951-1959, 75 if born
  // 1960 or later. Required beginning date = April 1 of the following year, so an owner who dies at
  // an age above the starting age is treated as dying after the RBD.
  var START_YEAR = 2026;
  // --------------------------------------------------------------------------------------
  function lifeExp(age) { if (age < 0) age = 0; return age >= 120 ? SINGLE_LIFE[120] : SINGLE_LIFE[age]; }
  function startAge(birthYear) { return birthYear <= 1950 ? 72 : birthYear <= 1959 ? 73 : 75; }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  function money(x) { return moneyFmt.format(isFinite(x) && Math.abs(x) >= 0.005 ? x : 0); }
  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function val(id) { return document.getElementById(id).value; }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function fillRows(id, rows) {
    var body = document.getElementById(id);
    body.textContent = '';
    rows.forEach(function (cells) {
      var tr = document.createElement('tr');
      cells.forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }
  function fillList(id, items) {
    var ul = document.getElementById(id);
    ul.textContent = '';
    items.forEach(function (t) { var li = document.createElement('li'); li.textContent = t; ul.appendChild(li); });
  }

  function ownerPhase(birthYear, bal, rate, deathYear) {
    var b = bal, rows = [], total = 0, sa = startAge(birthYear);
    for (var y = START_YEAR; y <= deathYear; y++) {
      var age = y - birthYear, rmd = 0, d = null;
      // An owner who dies in the year they reach the starting age dies before the RBD: no RMD due.
      if (age > sa || (age === sa && y < deathYear)) { d = UNIFORM[Math.min(120, age)]; rmd = Math.min(Math.max(0, b * (1 + rate)), b / d); }
      if (d !== null) rows.push([String(y), String(age), money(b), d.toFixed(1), money(rmd)]);
      total += rmd;
      b = Math.max(0, b * (1 + rate) - rmd);
    }
    return { balance: b, rows: rows, total: total };
  }
  // Heir phase for one path. path: 'stretch' or 'ten'.
  function heirPhase(path, p) {
    var b = p.bal, side = 0, taxPaid = 0, out = [], last = null;
    var tax = path === 'stretch' ? p.tax : p.tax10;
    for (var y = p.deathYear + 1; y <= p.horizon; y++) {
      var end = Math.max(0, b * (1 + p.rate)), d = p.div(y), w;
      var minW = d <= 1 ? end : Math.min(end, b / d);
      if (path === 'stretch') w = minW;
      else {
        var k = y - p.deathYear;
        if (k >= 10) w = end;
        else {
          var req = p.afterRbd ? minW : 0;
          w = p.strategy === 'even' ? Math.max(req, end / (10 - k + 1)) : req;
        }
      }
      if (b <= 0.005) w = 0;
      if (w > 0.005) last = y;
      taxPaid += w * tax;
      side = side * (1 + p.rate * (1 - p.gainTax)) + w * (1 - tax);
      b = Math.max(0, end - w);
      out.push({ w: w, bal: b });
    }
    return { rows: out, tax: taxPaid, value: side + b * (1 - tax), last: last };
  }

  function update() {
    var by = Math.round(num('sxOwnerBirth')), deathAge = Math.round(num('sxDeathAge')), bal = num('sxBalance'),
        hb = Math.round(num('sxBenBirth')), rate = num('sxRate'), tax = num('sxTax'), tax10 = num('sxTax10'),
        gainTax = num('sxGainTax'), strategy = val('sxStrategy');
    var error = document.getElementById('sxError'), err = '';
    if ([by, deathAge, bal, hb, rate, tax, tax10, gainTax].some(isNaN) || by < 1926 || by > 2010 || bal < 0 ||
        rate < -50 || rate > 30 || [tax, tax10, gainTax].some(function (x) { return x < 0 || x > 60; }))
      err = 'Enter an owner birth year from 1926 to 2010, a balance of $0 or more, a return from -50% to 30% and tax rates from 0% to 60%.';
    else if (deathAge < START_YEAR - by || deathAge > 120)
      err = 'The assumed age at death must be from ' + (START_YEAR - by) + " (the owner's age in " + START_YEAR + ') to 120.';
    else if (hb < 1900 || hb > by + deathAge)
      err = 'The beneficiary must be born by the year of the owner’s death (' + (by + deathAge) + ').';
    else if (hb <= by + 10)
      err = 'A beneficiary born no more than 10 years after the owner can still use the stretch, so there is nothing to compare. Enter a later year of birth.';
    error.hidden = !err;
    if (err) { error.textContent = err; return; }

    var r = rate / 100, deathYear = by + deathAge, afterRbd = deathAge > startAge(by);
    var owner = ownerPhase(by, bal, r, deathYear);
    var ownerLE0 = lifeExp(deathAge), heirLE0 = lifeExp(deathYear + 1 - hb);
    var div = function (y) {
      var heir = heirLE0 - (y - deathYear - 1);
      return afterRbd ? Math.max(heir, ownerLE0 - (y - deathYear)) : heir;
    };
    // Stretch ends when the divisor reaches 1 or less.
    var stretchEnd = deathYear + 1;
    while (div(stretchEnd) > 1 && stretchEnd < deathYear + 130) stretchEnd++;
    var p = { bal: owner.balance, rate: r, tax: tax / 100, tax10: tax10 / 100, gainTax: gainTax / 100, deathYear: deathYear,
              afterRbd: afterRbd, div: div, strategy: strategy, horizon: Math.max(stretchEnd, deathYear + 10) };
    var st = heirPhase('stretch', p), ten = heirPhase('ten', p);

    set('sxInheritLabel', 'Inherited balance (end of ' + deathYear + ')');
    set('sxInherit', money(owner.balance));
    set('sxStretchLabel', 'After-tax wealth with the stretch (' + p.horizon + ')');
    set('sxStretchValue', money(st.value));
    set('sxTenLabel', 'After-tax wealth with the 10-year rule (' + p.horizon + ')');
    set('sxTenValue', money(ten.value));
    set('sxLost', money(st.value - ten.value));
    set('sxStretchSpan', (deathYear + 1) + '–' + stretchEnd + ' (' + (stretchEnd - deathYear) + ' years, to heir age ' + (stretchEnd - hb) + ')');
    set('sxTenSpan', 'December 31, ' + (deathYear + 10) + (afterRbd ? ' (annual RMDs in years 1–9)' : ' (no annual RMDs)'));
    set('sxOwnerTotal', money(owner.total));
    set('sxTaxes', money(st.tax) + ' / ' + money(ten.tax));
    var note = 'The owner dies in ' + deathYear + ' at ' + deathAge + (afterRbd ? ', after their required beginning date' : ', before their required beginning date') +
               '. The heir is ' + (deathYear + 1 - hb) + ' in ' + (deathYear + 1) + ', with a starting life expectancy of ' + heirLE0.toFixed(1) + ' years. ' +
               'Both paths are valued at the end of ' + p.horizon + ', with the 10-year rule’s withdrawals invested in a taxable account until then.';
    if (!afterRbd && strategy === 'min') note += ' With no annual RMDs, the minimum path leaves everything to year 10, which usually means a much higher tax bracket that year.';
    set('sxNote', note);
    var rows = [];
    for (var i = 0; i < st.rows.length; i++) {
      var y = deathYear + 1 + i;
      if (st.rows[i].w <= 0.005 && ten.rows[i].w <= 0.005 && st.rows[i].bal <= 0.005 && ten.rows[i].bal <= 0.005) break;
      rows.push([String(y), String(y - hb), money(st.rows[i].w), money(st.rows[i].bal), money(ten.rows[i].w), money(ten.rows[i].bal)]);
    }
    fillRows('sxHeir', rows);
    fillRows('sxOwner', owner.rows.length ? owner.rows : [['—', '—', '—', '—', 'No RMD before death']]);
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('sxForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
